codigo_corregido:
let resizeHandler = null;

function openModal() {
  const modal = document.createElement('div');
  modal.className = 'modal';
  document.body.appendChild(modal);

  resizeHandler = () => adjustModalSize(modal);
  window.addEventListener('resize', resizeHandler);
}

function closeModal() {
  const modal = document.querySelector('.modal');
  if (modal) modal.remove();

  if (resizeHandler) {
    window.removeEventListener('resize', resizeHandler);
    resizeHandler = null;
  }
}

codigo_optimizado:
class Modal {
  constructor() {
    this.element = null;
    this.resizeHandler = this.handleResize.bind(this);
  }

  open() {
    this.element = document.createElement('div');
    this.element.className = 'modal';
    document.body.appendChild(this.element);
    window.addEventListener('resize', this.resizeHandler);
  }

  handleResize() {
    if (this.element) adjustModalSize(this.element);
  }

  close() {
    if (this.element) {
      this.element.remove();
      this.element = null;
    }
    window.removeEventListener('resize', this.resizeHandler);
  }
}

pregunta_transferencia:
Analiza el siguiente snippet. El desarrollador *intenta* limpiar usando `removeEventListener` pasando una función que *parece* idéntica a la registrada, pero **la fuga persiste**. ¿Por qué falla la limpieza y cómo modificarías el registro original para que `removeEventListener` funcione correctamente sin cambiar la firma de la llamada de limpieza?

javascript
// Registro
window.addEventListener('resize', () => console.log('A'));

// ... tiempo después ...
// Intento de limpieza
window.removeEventListener('resize', () => console.log('A'));


**Pista:** Piensa en **identidad de función** (referencia en memoria) vs **igualdad estructural** (mismo código). Las *arrow functions* inline se evalúan como **objetos función distintos** cada vez que se ejecuta la línea. `removeEventListener` compara **referencias estrictas (`===`)**, no el texto del código. Para resolverlo, necesitas **estabilizar la referencia** (guardar la función en una variable/constante *fuera* del flujo de ejecución repetido) para que el registro y la baja apunten al *mismo objeto función* en memoria.

